import{_ as a,o as t,c as o,a as n}from"./app.CYXXef1p.js";const p=JSON.parse('{"title":"Human-Agent Collaboration (HAC) & HITL Patterns (WP-4001..4009)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/HAC_AND_HITL_PATTERNS.md","filePath":"reference/HAC_AND_HITL_PATTERNS.md","lastUpdated":1771753292000}'),r={name:"reference/HAC_AND_HITL_PATTERNS.md"};function i(s,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="human-agent-collaboration-hac-hitl-patterns-wp-4001-4009" tabindex="-1">Human-Agent Collaboration (HAC) &amp; HITL Patterns (WP-4001..4009) <a class="header-anchor" href="#human-agent-collaboration-hac-hitl-patterns-wp-4001-4009" aria-label="Permalink to &quot;Human-Agent Collaboration (HAC) &amp; HITL Patterns (WP-4001..4009)&quot;">​</a></h1><p>This document defines the interaction patterns for seamless <strong>Human-Agent Collaboration</strong> within <code>thegent</code>.</p><h2 id="_1-interaction-patterns" tabindex="-1">1. Interaction Patterns <a class="header-anchor" href="#_1-interaction-patterns" aria-label="Permalink to &quot;1. Interaction Patterns&quot;">​</a></h2><p><code>thegent</code> supports three primary collaboration modes:</p><h3 id="_1-1-supervisory-loop-human-in-the-loop" tabindex="-1">1.1 Supervisory Loop (Human-in-the-Loop) <a class="header-anchor" href="#_1-1-supervisory-loop-human-in-the-loop" aria-label="Permalink to &quot;1.1 Supervisory Loop (Human-in-the-Loop)&quot;">​</a></h3><ul><li><strong>Pattern</strong>: Agent proposes an action; <code>PolicyEngine</code> triggers a &quot;Human Review&quot; requirement based on <code>Risk_Score</code>.</li><li><strong>UX</strong>: The <strong>Operator Cockpit</strong> displays the proposed change (diff) and the agent&#39;s rationale.</li><li><strong>Actions</strong>: Approve, Deny, or Edit (Modify the proposal before execution).</li></ul><h3 id="_1-2-active-learning-human-as-a-teacher" tabindex="-1">1.2 Active Learning (Human-as-a-Teacher) <a class="header-anchor" href="#_1-2-active-learning-human-as-a-teacher" aria-label="Permalink to &quot;1.2 Active Learning (Human-as-a-Teacher)&quot;">​</a></h3><ul><li><strong>Pattern</strong>: When the agent is uncertain (Confidence &lt; Threshold), it explicitly asks for clarification.</li><li><strong>UX</strong>: A &quot;Clarification Request&quot; appears in the cockpit.</li><li><strong>Feedback</strong>: The human&#39;s response is injected into the context and stored in the <strong>Calibration Feedback Loop</strong> (WP-4008) to improve future performance.</li></ul><h3 id="_1-3-human-as-a-tool-haat" tabindex="-1">1.3 Human-as-a-Tool (HaaT) <a class="header-anchor" href="#_1-3-human-as-a-tool-haat" aria-label="Permalink to &quot;1.3 Human-as-a-Tool (HaaT)&quot;">​</a></h3><ul><li><strong>Pattern</strong>: The agent can call a specialized <code>ask_human</code> tool for tasks that require human-only capabilities (e.g., &quot;Review UI feel,&quot; &quot;Check Slack for approval&quot;).</li><li><strong>UX</strong>: The tool call pauses the agent execution and waits for human input (asynchronous or synchronous).</li></ul><h2 id="_2-autonomy-transitions" tabindex="-1">2. Autonomy Transitions <a class="header-anchor" href="#_2-autonomy-transitions" aria-label="Permalink to &quot;2. Autonomy Transitions&quot;">​</a></h2><p>The <strong>Autonomy Gradient Control</strong> (from Phase 4) manages the frequency of these patterns:</p><table tabindex="0"><thead><tr><th>Level</th><th>HITL Frequency</th><th>Learning Mode</th></tr></thead><tbody><tr><td><strong>Manual</strong></td><td>100% (Every action)</td><td>Continuous feedback.</td></tr><tr><td><strong>Guarded</strong></td><td>High-risk only.</td><td>Targeted feedback.</td></tr><tr><td><strong>Supervised</strong></td><td>Exception-based.</td><td>Passive learning.</td></tr><tr><td><strong>Autonomous</strong></td><td>Minimal (Alerts only).</td><td>Post-hoc analysis.</td></tr></tbody></table><h2 id="_3-intervention-override-wp-4009" tabindex="-1">3. Intervention &amp; Override (WP-4009) <a class="header-anchor" href="#_3-intervention-override-wp-4009" aria-label="Permalink to &quot;3. Intervention &amp; Override (WP-4009)&quot;">​</a></h2><p>At any time, a human operator can &quot;Intervene&quot;:</p><ol><li><strong>Pause</strong>: Halt all active agents in the swarm.</li><li><strong>Snapshot</strong>: Capture the current world state.</li><li><strong>Override</strong>: Force-update the <code>WORK_STREAM.md</code> or a specific file.</li><li><strong>Resume</strong>: Restart agents with the new state.</li></ol><p>Every intervention is recorded in the <strong>Immutable Audit Trail</strong> with a mandatory <code>Override_Rationale</code>.</p><hr><p><em>Cross-ref: <a href="./PHASE_4_COCKPIT_UX_DEPTH.html">PHASE_4_COCKPIT_UX_DEPTH.md</a> | <a href="./../guides/AGENT_DEBUGGING_AND_REMEDIATION_GUIDE.html">AGENT_DEBUGGING_AND_REMEDIATION_GUIDE.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',31)])])}const m=a(r,[["render",i]]);export{p as __pageData,m as default};
